import java.util.Objects;

public final class ThreadSafeBoundedBuffer<T> {
    private final T[] array;
    private int head = 0, tail = 0, count = 0;

    @SuppressWarnings("unchecked")
    public ThreadSafeBoundedBuffer(int capacity) {
        this.array = (T[]) new Object[capacity];
    }

    // Correct usage of wait() inside a synchronized block and a while-loop
    public synchronized void put(T item) throws InterruptedException {
        while (count == array.length) {
            wait(); // Releases monitor lock, enters Wait Set, guards against spurious wakeups
        }
        array[tail] = item;
        tail = (tail + 1) % array.length;
        count++;
        notifyAll(); // Wakes up all waiting threads to re-evaluate their loop conditions
    }

    public synchronized T take() throws InterruptedException {
        while (count == 0) {
            wait();
        }
        T item = array[head];
        array[head] = null; // Prevent memory leak
        head = (head + 1) % array.length;
        count--;
        notifyAll();
        return item;
    }

    // Standard, robust implementation of equals, hashCode, and toString
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ThreadSafeBoundedBuffer<?> that = (ThreadSafeBoundedBuffer<?>) o;
        return count == that.count && Objects.deepEquals(array, that.array);
    }

    @Override
    public int hashCode() {
        return Objects.hash(count, Objects.hashCode(array));
    }

    @Override
    public String toString() {
        return String.format("BoundedBuffer[size=%d, capacity=%d]", count, array.length);
    }
}
